#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Install dependencies and verify the result: an install that Finder interrupts (.DS_Store,
# ENOTEMPTY) can exit 0 and leave packages half written. Run in an Orca terminal:
#   exec ./scripts/orca/install-main.sh
#       the main checkout, after a merge that changed package-lock.json;
#   exec ./scripts/orca/install-main.sh <NNN-slug>
#       the plan worktree, after an executor changed the dependencies in package files:
#       `npm_config_cache="$PWD/.npm-cache" npm install --no-audit --no-fund` updates package-lock.json first (outside the sandbox, with network),
#       then the install runs from the lockfile. The executor never installs.
# Retries once. Prints "INSTALL OK" or "INSTALL FAILED: <step>"; output goes to
# .scratch/tmp/install-main.log of the checkout it ran in.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1
if [ -n "${1:-}" ]; then
  cd "/Users/serhii/Developer/emdash-images/.worktrees/emdash-images/$1" || { echo "INSTALL FAILED: no worktree $1"; exit 1; }
fi

mkdir -p .scratch/tmp
log=.scratch/tmp/install-main.log
: > "$log"
fail() { echo "INSTALL FAILED: $1" | tee -a "$log"; exit 1; }

installed() { npm ls --depth=0 >> "$log" 2>&1; }

if [ -n "${1:-}" ]; then
  echo "=== update package-lock.json" | tee -a "$log"
  npm_config_cache="$PWD/.npm-cache" npm install --no-audit --no-fund >> "$log" 2>&1 || npm_config_cache="$PWD/.npm-cache" npm install --no-audit --no-fund >> "$log" 2>&1 || fail "update (see $log)"
fi

for attempt in 1 2; do
  echo "=== install, attempt $attempt" | tee -a "$log"
  if npm_config_cache="$PWD/.npm-cache" npm ci >> "$log" 2>&1 && installed; then
    git status --short -- package-lock.json | tee -a "$log"
    echo "INSTALL OK" | tee -a "$log"
    exit 0
  fi
done
fail "install or verification (see $log)"
